@startuml

class Movie {
  + Title : string
}

class Order {
  + OrderDate : date
}

class User {
  + Name : string
}

class Subscriber {
  + CardNumber : string
  + Balance : float
}

class Card {
  + Balance : float
}

User "1" -- "0..*" Order : places
Order "1" -- "1..*" Movie : contains
User "1" -- "0..1" Subscriber : is a
Subscriber "1" -- "1" Card : has

@enduml

